#!/usr/bin/env python3
"""Apply the Strategy 2 optimization-domain extraction and verification split.

This script is intentionally deterministic and idempotent.  It is run by the
branch-specific GitHub Actions workflow because the chat runtime has no direct
network checkout of the repository.
"""

from __future__ import annotations

from pathlib import Path
import re
import textwrap

ROOT = Path(__file__).resolve().parents[1]
PAPER = ROOT / "arrange" / "paper_draft"
FORMAL = ROOT / "formalization" / "strategy2_optimization"


def write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    normalized = textwrap.dedent(content).strip() + "\n"
    path.write_text(normalized, encoding="utf-8")


def replace_once(text: str, old: str, new: str, *, path: Path) -> str:
    if old not in text:
        if new in text:
            return text
        raise RuntimeError(f"expected text not found in {path}: {old[:100]!r}")
    if text.count(old) != 1:
        raise RuntimeError(f"expected one occurrence in {path}, found {text.count(old)}")
    return text.replace(old, new, 1)


