def split_verification() -> list[str]:
    path = PAPER / "04_strategy2_verification.tex"
    text = path.read_text(encoding="utf-8")
    prefix = "04e_strategy2_verification_"
    marker = r"\section{Exact Local Demand Calculus}"
    if marker not in text:
        inputs = re.findall(r"\\input\{(04e_strategy2_verification_[^}]+)\}", text)
        if not inputs:
            raise RuntimeError("verification marker and split inputs are both absent")
        missing = [name for name in inputs if not (PAPER / f"{name}.tex").exists()]
        if missing:
            raise RuntimeError(f"split verification modules are missing: {missing}")
        return inputs

    for stale in PAPER.glob(prefix + "*.tex"):
        stale.unlink()

    first = text.index(marker)
    tail = text[first:]
    pattern = re.compile(r"(?m)^\\section\{([^}]*)\}\s*$")
    matches = list(pattern.finditer(tail))
    if not matches:
        raise RuntimeError("no verification sections found")

    modules = ["04e_strategy2_verification_01_registered_applications"]
    write(PAPER / f"{modules[0]}.tex", FILES["__REGISTRY__"])

    used: set[str] = set()
    for pos, match in enumerate(matches):
        start = match.start()
        end = matches[pos + 1].start() if pos + 1 < len(matches) else len(tail)
        segment = tail[start:end]
        idx = pos + 2
        title = match.group(1)
        slug = re.sub(r"\\[A-Za-z]+|[^A-Za-z0-9]+", "_", title).strip("_").lower()
        if not slug:
            slug = f"section_{idx}"
        base_slug = slug
        n = 2
        while slug in used:
            slug = f"{base_slug}_{n}"
            n += 1
        used.add(slug)
        name = f"{prefix}{idx:02d}_{slug}"
        modules.append(name)
        write(PAPER / f"{name}.tex", segment)

    wrapper = (
        "% Input-only wrapper generated by tools/apply_strategy2_optimization_extraction.py.\n"
        "% The application registry and every technical section have separate owners.\n\n"
        + "\n".join(fr"\input{{{name}}}" for name in modules)
        + "\n"
    )
    write(path, wrapper)
    return modules


