def validate_generated_sources(modules: list[str]) -> None:
    required = [
        "prob:s2-t3-endpoint",
        "prob:s2-rescuer",
        "prob:s2-vd-adjacent",
        "prob:s2-vd-nonadjacent",
        "prop:s2-t3-source-bridge",
        "sec:strategy2-reader",
        "prop:reader-common-two-gap",
        "prop:reader-ce1-one-gap",
        "prop:reader-ce2-one-gap",
        "prop:reader-demand-branches",
    ]
    paths = (
        list(PAPER.glob("04_strategy2*.tex"))
        + list(PAPER.glob("04d_strategy2*.tex"))
        + list(PAPER.glob("04e_strategy2*.tex"))
    )
    corpus = "\n".join(p.read_text(encoding="utf-8") for p in paths)
    missing = [label for label in required if label not in corpus]
    if missing:
        raise RuntimeError(f"missing required labels after split: {missing}")

    forbidden = [
        "must be supplied as a finite union",
        "placement-defined suprema",
        "domains still require extraction",
    ]
    active = "\n".join(
        (PAPER / name).read_text(encoding="utf-8")
        for name in [
            "04_strategy2_optimization_problems.tex",
            "04_strategy2_optimization_t3.tex",
            "04_strategy2_optimization_rescuer.tex",
            "04_strategy2_optimization_vd.tex",
        ]
    )
    found = [phrase for phrase in forbidden if phrase in active]
    if found:
        raise RuntimeError(f"stale incomplete-interface text remains: {found}")

    lean = (FORMAL / "Strategy2OptimizationProblems.lean").read_text(encoding="utf-8")
    theorem_names = [
        "problemS2E1", "problemS2E2", "problemS2R1", "problemS2R2",
        "problemS2T3", "problemS2SCT", "problemS2SCV",
        "problemS2VDAdjacentSupport", "problemS2VDAdjacentNoSupport",
        "problemS2VDNonadjacent",
    ]
    missing_theorems = [name for name in theorem_names if f"theorem {name}" not in lean]
    if missing_theorems or lean.count("sorry") < len(theorem_names):
        raise RuntimeError(
            f"Lean problem shell incomplete: missing={missing_theorems}, "
            f"sorry_count={lean.count('sorry')}"
        )


def main() -> None:
    expanded = dict(FILES)
    expanded.pop("__REGISTRY__")
    for relative, content in expanded.items():
        write(ROOT / relative, content)

    remaining = PAPER / "04_strategy2_optimization_remaining.tex"
    if remaining.exists():
        remaining.unlink()

    update_summary_certificates()
    update_main()
    modules = split_verification()
    update_roadmap(modules)
    update_symbols()
    update_source_ledger(modules)
    update_review_notes()
    validate_generated_sources(modules)


if __name__ == "__main__":
    main()
